upper=dict(id='midpoint-deterministic-overview',title='Deterministic guarantees: source Theorem1.1 (informal)',anchor='Theorem1.1; precise Theorems3.1/4.1 and source Section2 algorithms',statement='For 0<epsilon<=sqrt(d)/2, Heun initialized at the unique minimizer x_star reaches sqrt(alpha)W2<=epsilon with the displayed gradient-query bound. Exponential midpoint with friction2sqrt(beta), X0=x_star and independent P0~N(0,I_d) has the second bound for its position law. Tilde O suppresses logarithms. This faithfully restates the labelled informal theorem; exact schedules/universal constants of3.1/4.1 remain separate source obligations.',assumptions=base_assumptions+['0<epsilon<=sqrt(d)/2. Heun starts at x_star; exponential midpoint has X0=x_star, independent standard Gaussian momentum and friction2sqrt(beta).'],formula=r'Q_{\rm Heun}=\widetilde O(\kappa^{4/3}d^{1/3}\varepsilon^{-2/3}),\qquad Q_{\rm ExpMid}=\widetilde O(\kappa^{5/4}d^{1/4}\varepsilon^{-1/2}),\qquad\sqrt\alpha W_2\le\varepsilon.',steps=[step('Preserve the genuine transition and stationary error',r'\nu_N=\nu_0 K_h^N,\qquad W_2(\nu_N,\pi)\le W_2(\nu_N,\pi_h)+W_2(\pi_h,\pi).','The actual method kernel, invariant law and finite-step contraction must be proved separately; stationarity is not an oracle premise.','Sections2-4; AppendicesA/B'),step('Use cancellation under only C2 Hessian bounds',r'\alpha I\preceq\nabla^2V\preceq\beta I.','Heun uses a discrete Poisson corrector, Malliavin–Stein and Gaussian smoothing. Exponential midpoint uses weighted negative-Sobolev divergence cancellation and transport. Missing regularity details must be supplied without adding higher derivative bounds to the source theorem.','AppendicesA/B/E')],boundary='Source-pinned phase3 plan only; no new midpoint Lean theorem, actual kernel, invariant bias, schedule, convergence or complexity certificate is claimed.')
lower=dict(id='midpoint-lower-overview',title='Stationary and finite-iteration lower bounds: source Theorem1.2 (informal)',anchor='Theorem1.2/Table1; Proposition5.1,Theorem5.2,Propositions5.3/6.1/6.2,Corollary6.3',statement='For each Table1 method and every sufficiently small normalized step h, there is a strongly convex smooth target of bounded condition number and a position initialization with expected potential gap at most C*d. For every sufficiently small epsilon, attaining sqrt(alpha)W2(position law after N steps,pi)<=epsilon requires the Table1 lower-bound number of queries up to logarithms. For underdamped methods the initial momentum is independent standard Gaussian. This is the source-labelled informal overview; stationary bias and finite-iteration claims keep their separate precise source contracts.',assumptions=base_assumptions+['Existential target and initialization, bounded condition number, sufficiently small normalized h and epsilon; E[V(X0)-V(x_star)]<=C*d. Underlying momentum is standard Gaussian and independent of X0.','Poisson midpoint uses at least2 grid points and constant expected gradients per batch. Exact stationary/finitestep quantifiers and source constants remain in the named precise results.'],formula=r'Q_{\rm Heun}\gtrsim d^{1/3}\varepsilon^{-2/3},\quad Q_{\rm ExpMid}\gtrsim d^{1/4}\varepsilon^{-1/2},\quad Q_{\rm RLMC,PLMC,RULMC,PULMC}\gtrsim d^{1/3}\varepsilon^{-1/3}.',steps=[step('Keep deterministic bias and finite initialization distinct',r'\mathbb E[V(X_0)-V(x_\star)]\le Cd.','Oscillatory targets yield the deterministic Heun obstruction; Gaussian/anisotropic Gaussian targets give exponential-midpoint bounds. Stationary bias alone does not establish every finite-step initialization claim.','Section5; Corollary6.3'),step('Track shared randomized covariance fluctuations',r'X\mid\mathcal H\sim\mathcal N(0,\Sigma(\mathcal H)).','For the actual randomized methods, shared quadrature choices induce common covariance fluctuations. The source Section6 calculations and finite-step passage must be formalized under their actual randomness; independent coordinates must not be invented unconditionally.','Section6; AppendixD')],boundary='Source-pinned phase3 plan only; neither a lower-bound oracle certificate nor finite-step proof is claimed. Upper-bound and hardness lanes stay separate until method/accuracy/initialization/query contracts match.')
